package br.com.pacto.recrutamento.infra.templatevaga; import br.com.pacto.recrutamento.app.templatevaga.RequisitoTemplateVagaRepositorio; import br.com.pacto.recrutamento.core.entities.RequisitoTemplateVaga; import org.springframework.stereotype.Repository; import java.util.*; import java.util.stream.*; @Repository class RequisitoTemplateVagaJpaAdapter implements RequisitoTemplateVagaRepositorio {private final RequisitoTemplateVagaJpaRepository r;private final RequisitoTemplateVagaJpaMapper m;RequisitoTemplateVagaJpaAdapter(RequisitoTemplateVagaJpaRepository r,RequisitoTemplateVagaJpaMapper m){this.r=r;this.m=m;}public Optional<RequisitoTemplateVaga> buscarAtivoPorId(UUID id){return id==null?Optional.empty():r.findByIdAndExcluidoEmIsNull(id).map(m::paraDominio);}public List<RequisitoTemplateVaga> listarAtivosDoTemplate(UUID id){return r.findByTemplateVagaIdAndExcluidoEmIsNull(id).stream().map(m::paraDominio).collect(Collectors.toList());}public RequisitoTemplateVaga salvar(RequisitoTemplateVaga x){return m.paraDominio(r.save(m.paraEntidade(x)));}}
